import { useIntl } from '@kne/react-intl';
import withLocale from './withLocale';
import useOverflowItems from './useOverflowItems';
import OverflowItemsShare from './OverflowItemsShare';
import style from './style.module.scss';

const cx = (...names) => names.filter(Boolean).join(' ');

const OverflowItems = withLocale(props => {
  const {
    items = [],
    renderItem,
    renderMore,
    gap = 8,
    strategy = 'asc',
    enabled = true,
    beforeReady = 'all',
    debounce = 100,
    safetyGap,
    expandHysteresis,
    settle,
    maxSettle,
    itemSelector,
    observeParent,
    shareKey,
    className,
    measureClassName,
    contentClassName,
    style: styleProp
  } = Object.assign({}, props);

  const { formatMessage } = useIntl();
  const list = Array.isArray(items) ? items : [];
  const { setContainerRef, setMeasureRef, setMoreMeasureRef, visibleCount, ready, hiddenCount, shouldMeasure } = useOverflowItems({
    itemCount: list.length,
    items: list,
    shareKey,
    enabled,
    strategy,
    gap,
    safetyGap,
    expandHysteresis,
    settle,
    maxSettle,
    debounce,
    beforeReady,
    itemSelector,
    observeParent
  });

  const visibleItems = ready || beforeReady === 'all' ? list.slice(0, visibleCount) : list.slice(0, Math.max(visibleCount, Math.min(1, list.length)));
  const hiddenItems = list.slice(visibleCount);
  const showMore = ready && hiddenCount > 0;

  const moreCtx = {
    hiddenItems,
    hiddenCount,
    visibleCount,
    ready
  };

  const moreNode = showMore ? typeof renderMore === 'function' ? renderMore(moreCtx) : <span className={style['more']}>{formatMessage({ id: 'more' })}</span> : null;

  const measureMoreNode =
    typeof renderMore === 'function' ? (
      renderMore({ ...moreCtx, hiddenItems: list.slice(1), hiddenCount: Math.max(0, list.length - 1), visibleCount: Math.min(1, list.length) })
    ) : (
      <span className={style['more']}>{formatMessage({ id: 'more' })}</span>
    );

  return (
    <div className={cx(style['root'], !ready && beforeReady === 'min' && style['is-pending'], className)} style={styleProp}>
      {shouldMeasure ? (
        <div ref={setMeasureRef} className={cx(style['measure'], measureClassName)} aria-hidden style={{ gap }}>
          {list.map((item, index) => (
            <div key={index} data-overflow-item>
              {typeof renderItem === 'function' ? renderItem(item, index, { visible: false, ready }) : item}
            </div>
          ))}
          <div ref={setMoreMeasureRef} data-overflow-more>
            {measureMoreNode}
          </div>
        </div>
      ) : null}
      <div ref={setContainerRef} className={cx(style['content'], contentClassName)} style={{ gap }}>
        {visibleItems.map((item, index) => (
          <div key={index} data-overflow-visible-item>
            {typeof renderItem === 'function' ? renderItem(item, index, { visible: true, ready }) : item}
          </div>
        ))}
        {moreNode}
      </div>
    </div>
  );
});

OverflowItems.Share = OverflowItemsShare;

export default OverflowItems;
